mapper.select:
select s.id, s.merchant_id, s.name, s.location, s.business_hours, s.description, s.status, s.create_time, s.update_time, m.name merchantName, (select count(*) from dish d where d.stall_id = s.id) dishCount from stall s left join merchant m on s.merchant_id = m.id
s.merchant_id = #{merchantId}
and s.name like CONCAT('%', #{name}, '%')
and s.status = #{status}
order by s.merchant_id asc, s.id asc
